{
  "part": {
    "name": "Rounded-end bar with blended hollow boss (blind bore)",
    "description": "Single solid part consisting of a long rectangular bar with one rounded planform end, and a hollow cylindrical boss mounted on one face via a smooth blend. The boss contains a blind cylindrical bore (open at top, closed at bottom).",
    "source_views": [
      "front",
      "back",
      "left",
      "right",
      "top",
      "bottom",
      "toprightiso"
    ],
    "symmetry_note": "Model appears symmetric about the mid-plane of the bar thickness (approx. plane z=4 in STEP bbox), with boss and rounded end centered on that plane."
  },
  "Section": [
    {
      "id": "S1",
      "name": "Main bar (prismatic body)",
      "features included": [
        "Primary structural spine/beam",
        "Flat mounting/support faces (broad planar faces)",
        "Square end face (termination at one end)"
      ],
      "function intent": "Provide a stiff lever/strap-like body to carry and transmit loads to/from the boss and to interface with other structures along its flat faces.",
      "physical behavior": "Acts predominantly in bending and torsion as a long beam; planar faces provide stable contact and distribute bearing loads; end face acts as a hard stop/trim boundary.",
      "geometry": "Long rectangular prism/plate with constant cross-section over most of its length; one end is square (planar end face), the other transitions to a rounded end handled in a separate section. Faces are primarily planar with sharp edges except where intersecting blend/rounded-end topology creates additional edges.",
      "location": "Dominant body spanning the full length; excludes the rounded end surface and the boss/blend region surfaces.",
      "colour": {
        "R": 210,
        "G": 120,
        "B": 70
      },
      "major_faces": [
        {
          "face_code": "0000",
          "name": "Bar broad face A",
          "Brep_id": "FACE 1",
          "description": "Large planar face of the bar (one of the two opposite broad faces), bounded by rounded end and boss cut/blend edges."
        },
        {
          "face_code": "0001",
          "name": "Bar side face (low-Y side)",
          "Brep_id": "FACE 5",
          "description": "Long planar side face at the minimum Y extent of the bar, running full length including into the rounded end boundary."
        },
        {
          "face_code": "0002",
          "name": "Bar broad face B",
          "Brep_id": "FACE 6",
          "description": "Opposite large planar face of the bar (parallel to face 0000)."
        },
        {
          "face_code": "0003",
          "name": "Bar side face (high-Y main run)",
          "Brep_id": "FACE 8",
          "description": "Long planar side face at the maximum Y extent of the bar, present over the straight run away from boss/rounded-end interruptions."
        },
        {
          "face_code": "0004",
          "name": "Square end face",
          "Brep_id": "FACE 7",
          "description": "Planar termination face at the square end of the bar (max-X end)."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S1",
          "target id": "S5",
          "function relationship": "transmits_load",
          "structural relationship": "attached_to"
        },
        {
          "source id": "S1",
          "target id": "S3",
          "function relationship": "supports",
          "structural relationship": "supports"
        },
        {
          "source id": "S1",
          "target id": "S2",
          "function relationship": "distributes_stress",
          "structural relationship": "blends_into"
        }
      ]
    },
    {
      "id": "S2",
      "name": "Rounded bar end (planform radius end)",
      "features included": [
        "Rounded/contoured end for clearance and reduced stress concentration",
        "Local planar patch at the side boundary near the rounded transition"
      ],
      "function intent": "Provide a smooth end geometry for clearance, safer handling, and reduced stress concentration versus a sharp corner/end.",
      "physical behavior": "Reduces peak stress at the end and improves load flow in bending by removing sharp geometric discontinuities.",
      "geometry": "Cylindrical side surface forming the rounded end profile (extruded through thickness), plus a small planar patch at the adjacent side boundary created by topology where the rounded end meets the straight side and nearby features.",
      "location": "At the non-square end of the bar (the rounded end, near min-X of the STEP bbox).",
      "colour": {
        "R": 90,
        "G": 160,
        "B": 220
      },
      "major_faces": [
        {
          "face_code": "0005",
          "name": "Rounded end cylindrical side",
          "Brep_id": "FACE 0",
          "description": "Cylindrical surface forming the rounded end boundary of the bar (radius per STEP: 17.5)."
        },
        {
          "face_code": "0006",
          "name": "Small side planar patch near rounded end",
          "Brep_id": "FACE 2",
          "description": "Small planar face segment at the bar side boundary near the rounded end, created by local edge partitioning."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S2",
          "target id": "S1",
          "function relationship": "distributes_stress",
          "structural relationship": "blends_into"
        }
      ]
    },
    {
      "id": "S5",
      "name": "Boss-to-bar blend (saddle/fillet transition)",
      "features included": [
        "Smooth transition fillet/blend surface",
        "Stress-relief and load-path smoothing at boss root"
      ],
      "function intent": "Provide a smooth, robust root transition between the boss and the bar to lower stress concentration and improve manufacturability/strength.",
      "physical behavior": "Transfers load from boss into bar through a gradually changing curvature, reducing notch effects and improving fatigue resistance.",
      "geometry": "Single BSpline (freeform) surface wrapping around the boss root, blending from the bar planar faces into the boss cylindrical surface.",
      "location": "At the base of the boss where it meets the bar (near the boss centerline, around x≈0 region in STEP).",
      "colour": {
        "R": 160,
        "G": 110,
        "B": 200
      },
      "major_faces": [
        {
          "face_code": "0007",
          "name": "Root blend surface",
          "Brep_id": "FACE 9",
          "description": "BSpline blend/fillet surface connecting the boss outer cylinder to the bar faces around the boss footprint."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S5",
          "target id": "S1",
          "function relationship": "distributes_stress",
          "structural relationship": "blends_into"
        },
        {
          "source id": "S5",
          "target id": "S3",
          "function relationship": "transmits_load",
          "structural relationship": "attached_to"
        }
      ]
    },
    {
      "id": "S3",
      "name": "Outer boss (sleeve body and top rim)",
      "features included": [
        "Cylindrical boss / locating sleeve",
        "Top annular interface face (rim around bore opening)"
      ],
      "function intent": "Provide a raised locating/interface sleeve for a mating cylindrical component (pin/shaft/fastener) and to stiffen the local region around the bore.",
      "physical behavior": "Acts as a short cylindrical shell in compression/bearing; outer wall provides hoop stiffness and resists side loads transferred through the bore into the bar.",
      "geometry": "Outer cylindrical surface (radius per STEP: 7) plus the top annular planar face (outer rim) with a central opening.",
      "location": "Mounted on the bar near one end (around the boss centerline at x≈0, above the bar via the blend).",
      "colour": {
        "R": 80,
        "G": 180,
        "B": 120
      },
      "major_faces": [
        {
          "face_code": "0008",
          "name": "Boss outer cylindrical wall",
          "Brep_id": "FACE 10",
          "description": "Outer cylindrical surface of the boss (radius 7) extending from blend region to the top rim."
        },
        {
          "face_code": "0009",
          "name": "Boss top annular face",
          "Brep_id": "FACE 11",
          "description": "Top planar annulus (outer radius 7, inner radius 5) surrounding the bore opening."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S3",
          "target id": "S4",
          "function relationship": "locates_mating_part",
          "structural relationship": "contains_in"
        },
        {
          "source id": "S3",
          "target id": "S5",
          "function relationship": "transmits_load",
          "structural relationship": "attached_to"
        },
        {
          "source id": "S3",
          "target id": "S1",
          "function relationship": "transmits_load",
          "structural relationship": "supports"
        }
      ]
    },
    {
      "id": "S4",
      "name": "Blind bore (internal hole feature)",
      "features included": [
        "Cylindrical blind bore",
        "Bore bottom (end) face"
      ],
      "function intent": "Provide a guided cylindrical seat for a mating pin/shaft/fastener with a defined insertion depth (blind end).",
      "physical behavior": "Inner cylindrical wall provides radial constraint and bearing contact; bottom face provides axial stop to constrain insertion depth and axial DOF.",
      "geometry": "Inner cylindrical surface (radius per STEP: 5) open at the boss top, terminating at a flat circular bottom face.",
      "location": "Concentric within the boss, opening at the boss top face and stopping at an internal plane.",
      "colour": {
        "R": 230,
        "G": 210,
        "B": 90
      },
      "major_faces": [
        {
          "face_code": "0010",
          "name": "Bore cylindrical wall",
          "Brep_id": "FACE 3",
          "description": "Inner cylindrical surface of the blind bore (radius 5), coaxial with boss axis."
        },
        {
          "face_code": "0011",
          "name": "Bore bottom face",
          "Brep_id": "FACE 4",
          "description": "Planar circular face closing the blind bore at its bottom (area ≈ π·5^2)."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S4",
          "target id": "S3",
          "function relationship": "constrains_dof",
          "structural relationship": "contained_in"
        }
      ]
    }
  ]
}
